  "Checkout needs setup": "\u0627\u0644\u062F\u0641\u0639 \u064A\u062D\u062A\u0627\u062C \u0625\u0639\u062F\u0627\u062F\u064B\u0627",
  "Billing Portal ready": "\u0628\u0648\u0627\u0628\u0629 \u0627\u0644\u0641\u0648\u062A\u0631\u0629 \u062C\u0627\u0647\u0632\u0629",
  "Portal needs setup": "\u0627\u0644\u0628\u0648\u0627\u0628\u0629 \u062A\u062D\u062A\u0627\u062C \u0625\u0639\u062F\u0627\u062F\u064B\u0627",
  "Mode matches prices": "\u0627\u0644\u0648\u0636\u0639 \u0645\u062A\u0637\u0627\u0628\u0642 \u0645\u0639 \u0627\u0644\u0623\u0633\u0639\u0627\u0631",
  "Live/Test mismatch": "\u0639\u062F\u0645 \u062A\u0637\u0627\u0628\u0642 Live/Test",
  "Payout Destination": "\u0648\u062C\u0647\u0629 \u0627\u0644\u062A\u062D\u0648\u064A\u0644\u0627\u062A",
  "Bank accounts, payout schedule, identity and tax details are managed only inside Stripe.": "\u062A\u064F\u062F\u0627\u0631 \u0627\u0644\u062D\u0633\u0627\u0628\u0627\u062A \u0627\u0644\u0628\u0646\u0643\u064A\u0629 \u0648\u062C\u062F\u0648\u0644 \u0627\u0644\u062A\u062D\u0648\u064A\u0644\u0627\u062A \u0648\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0647\u0648\u064A\u0629 \u0648\u0627\u0644\u0636\u0631\u0627\u0626\u0628 \u062F\u0627\u062E\u0644 Stripe \u0641\u0642\u0637.",
  "Open Stripe Dashboard": "\u0641\u062A\u062D \u0644\u0648\u062D\u0629 Stripe",
  "Refresh Stripe Status": "\u062A\u062D\u062F\u064A\u062B \u062D\u0627\u0644\u0629 Stripe",
  "System logs unavailable": "\u0633\u062C\u0644\u0627\u062A \u0627\u0644\u0646\u0638\u0627\u0645 \u063A\u064A\u0631 \u0645\u062A\u0627\u062D\u0629",
  "Account blocks unavailable": "\u062D\u0638\u0631 \u0627\u0644\u062D\u0633\u0627\u0628\u0627\u062A \u063A\u064A\u0631 \u0645\u062A\u0627\u062D",
  "Account Block List": "\u0642\u0627\u0626\u0645\u0629 \u062D\u0638\u0631 \u0627\u0644\u062D\u0633\u0627\u0628\u0627\u062A",
  "Blocks survive account deletion and prevent re-registration while active.": "\u064A\u0628\u0642\u0649 \u0627\u0644\u062D\u0638\u0631 \u0628\u0639\u062F \u062D\u0630\u0641 \u0627\u0644\u062D\u0633\u0627\u0628 \u0648\u064A\u0645\u0646\u0639 \u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u062A\u0633\u062C\u064A\u0644 \u0645\u0627 \u062F\u0627\u0645 \u0641\u0639\u0627\u0644\u064B\u0627.",
  "No blocked emails": "\u0644\u0627 \u062A\u0648\u062C\u062F \u0639\u0646\u0627\u0648\u064A\u0646 \u0628\u0631\u064A\u062F \u0645\u062D\u0638\u0648\u0631\u0629",
  "Blocked": "\u0645\u062D\u0638\u0648\u0631",
  "Expired": "\u0645\u0646\u062A\u0647\u064A",
  "No reason provided": "\u0644\u0645 \u064A\u062A\u0645 \u062A\u062D\u062F\u064A\u062F \u0633\u0628\u0628",
