  "Example: 1-3,5,8": "\u0645\u062B\u0627\u0644: 1-3,5,8",
  "Leave empty for all pages": "\u0627\u062A\u0631\u0643\u0647 \u0641\u0627\u0631\u063A\u064B\u0627 \u0644\u0643\u0644 \u0627\u0644\u0635\u0641\u062D\u0627\u062A",
  "pages in this PDF": "\u0635\u0641\u062D\u0629 \u0641\u064A \u0645\u0644\u0641 PDF \u0647\u0630\u0627",
  "New page order": "\u062A\u0631\u062A\u064A\u0628 \u0627\u0644\u0635\u0641\u062D\u0627\u062A \u0627\u0644\u062C\u062F\u064A\u062F",
  "Enter every page once, separated by commas. Example: 3,1,2,4": "\u0623\u062F\u062E\u0644 \u0643\u0644 \u0635\u0641\u062D\u0629 \u0645\u0631\u0629 \u0648\u0627\u062D\u062F\u0629 \u0648\u0627\u0641\u0635\u0644 \u0628\u064A\u0646\u0647\u0627 \u0628\u0641\u0648\u0627\u0635\u0644. \u0645\u062B\u0627\u0644: 3,1,2,4",
