  "Original PDF": "\u0645\u0644\u0641 PDF \u0627\u0644\u0623\u0635\u0644\u064A",
  "Original PDF preview": "\u0645\u0639\u0627\u064A\u0646\u0629 \u0645\u0644\u0641 PDF \u0627\u0644\u0623\u0635\u0644\u064A",
