  "Choose no more than 12 PDF files.": "\u0627\u062E\u062A\u0631 12 \u0645\u0644\u0641 PDF \u0643\u062D\u062F \u0623\u0642\u0635\u0649.",
  "Choose at least two PDF files to merge.": "\u0627\u062E\u062A\u0631 \u0645\u0644\u0641\u064A PDF \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644 \u0644\u0644\u062F\u0645\u062C.",
  "The merged PDF cannot exceed 150 pages.": "\u0644\u0627 \u064A\u0645\u0643\u0646 \u0623\u0646 \u064A\u062A\u062C\u0627\u0648\u0632 \u0645\u0644\u0641 PDF \u0627\u0644\u0645\u062F\u0645\u062C 150 \u0635\u0641\u062D\u0629.",
  "The selected PDF files exceed the 120 MB combined safety limit.": "\u062A\u062A\u062C\u0627\u0648\u0632 \u0627\u0644\u0645\u0644\u0641\u0627\u062A \u0627\u0644\u0645\u062D\u062F\u062F\u0629 \u062D\u062F \u0627\u0644\u0623\u0645\u0627\u0646 \u0627\u0644\u0625\u062C\u0645\u0627\u0644\u064A \u0627\u0644\u0628\u0627\u0644\u063A 120 MB.",
  "PDF files must be larger than 0 bytes and no more than 50 MB each.": "\u064A\u062C\u0628 \u0623\u0646 \u064A\u0643\u0648\u0646 \u062D\u062C\u0645 \u0643\u0644 \u0645\u0644\u0641 PDF \u0623\u0643\u0628\u0631 \u0645\u0646 \u0635\u0641\u0631 \u0648\u0623\u0644\u0627 \u064A\u062A\u062C\u0627\u0648\u0632 50 MB.",
  "This file is not a valid PDF document.": "\u0647\u0630\u0627 \u0627\u0644\u0645\u0644\u0641 \u0644\u064A\u0633 \u0645\u0633\u062A\u0646\u062F PDF \u0635\u0627\u0644\u062D\u064B\u0627.",
  "PDF page count must be between 1 and 150 pages.": "\u064A\u062C\u0628 \u0623\u0646 \u064A\u0643\u0648\u0646 \u0639\u062F\u062F \u0635\u0641\u062D\u0627\u062A PDF \u0628\u064A\u0646 1 \u0648150 \u0635\u0641\u062D\u0629.",
  "This PDF is damaged or uses an unsupported format.": "\u0645\u0644\u0641 PDF \u062A\u0627\u0644\u0641 \u0623\u0648 \u064A\u0633\u062A\u062E\u062F\u0645 \u0635\u064A\u063A\u0629 \u063A\u064A\u0631 \u0645\u062F\u0639\u0648\u0645\u0629.",
  "This PDF exceeded the safe decompression limit.": "\u062A\u062C\u0627\u0648\u0632 \u0645\u0644\u0641 PDF \u062D\u062F \u0641\u0643 \u0627\u0644\u0636\u063A\u0637 \u0627\u0644\u0622\u0645\u0646.",
